const API_KEY = [REDACTED]'apiKey')
const WRONG_APIKEY = [REDACTED]'wrongApiKey')
const WAITING_TIME = Cypress.env('waitingTime')

describe(`Test API key required`, () => {
  before(() => {
    cy.deleteAllIndexes()
  })

  beforeEach(() => {
    cy.visit('/')
  })

  it('Should visit the dashboard', () => {
    cy.url().should('match', /\//)
  })

  it('Should find a text in modal requesting API key', () => {
    cy.contains('Enter your admin API key')
  })

  it('Should fail on wrong API key triggered with mouse click', () => {
    cy.get('div[aria-label=ask-for-api-key]').within(() => {
      cy.get('input[name="apiKey"]').as('apiKeyInput')
      cy.get('@apiKeyInput').type(WRONG_APIKEY)
      cy.get('@apiKeyInput').should('have.value', WRONG_APIKEY)
      cy.get('button').contains('Go').click()
      cy.wait(WAITING_TIME)
      cy.contains('The provided API key is invalid.')
    })
  })

  it('Should fail on wrong API key triggered with enter key', () => {
    cy.get('div[aria-label=ask-for-api-key]').within(() => {
      cy.get('input[name="apiKey"]').as('apiKeyInput')
      cy.get('@apiKeyInput').type(WRONG_APIKEY)
      cy.get('@apiKeyInput').should('have.value', WRONG_APIKEY)
      cy.get('@apiKeyInput').type('{enter}')
      cy.wait(WAITING_TIME)
      cy.contains('The provided API key is invalid.')
    })
  })

  it('Should accept valid API key', () => {
    cy.get('div[aria-label=ask-for-api-key]').within(() => {
      cy.get('input[name="apiKey"]').as('apiKeyInput')
      cy.get('@apiKeyInput').clear()
      cy.get('@apiKeyInput').type(API_KEY)
      cy.get('@apiKeyInput').should('have.value', API_KEY)
      cy.get('button').contains('Go').click()
      cy.wait(WAITING_TIME)
    })
    cy.contains('Welcome to')
  })

  it('Should display a modal with API key inside the API key modal button', () => {
    // Fill the first API key request (key is stored in RAM only, not persisted)
    cy.get('div[aria-label=ask-for-api-key]').within(() => {
      cy.get('input[name="apiKey"]').as('apiKeyInput')
      cy.get('@apiKeyInput').clear()
      cy.get('@apiKeyInput').type(API_KEY)
      cy.get('button').contains('Go').click()
    })
    cy.wait(WAITING_TIME)
    cy.contains('Welcome to')

    // Open the Api Key modal from the header (same session, key still in memory)
    cy.get('span').contains('Api Key').parent().click()
    cy.get('div[aria-label=settings-api-key]').within(() => {
      cy.get('input[name="apiKey"]').should('have.value', API_KEY)
    })
  })

  it('Should fail on API Key change inside the API key modal button', () => {
    // Fill the first API key request (key is stored in RAM only, not persisted)
    cy.get('div[aria-label=ask-for-api-key]').within(() => {
      cy.get('input[name="apiKey"]').as('apiKeyInput')
      cy.get('@apiKeyInput').clear()
      cy.get('@apiKeyInput').type(API_KEY)
      cy.get('button').contains('Go').click()
    })
    cy.wait(WAITING_TIME)
    cy.contains('Welcome to')

    // Open the Api Key modal from the header and try to change to an invalid key
    cy.get('span').contains('Api Key').parent().click()
    cy.get('div[aria-label=settings-api-key]').within(() => {
      cy.get('input[name="apiKey"]').as('apiKeyInput')
      cy.get('@apiKeyInput').clear()
      cy.get('@apiKeyInput').type(WRONG_APIKEY)
      cy.get('@apiKeyInput').should('have.value', WRONG_APIKEY)
      cy.get('button').contains('Go').click()
      cy.wait(WAITING_TIME)
      cy.contains('The provided API key is invalid.')
    })
  })
})

const WAITING_TIME = Cypress.env('waitingTime')

describe(`Test no API key required`, () => {
  before(() => {
    cy.deleteAllIndexes()
    cy.wait(WAITING_TIME)
  })

  beforeEach(() => {
    cy.visit('/')
  })

  it('Should visit the dashboard', () => {
    cy.url().should('match', /\//)
  })

  it('Should display the help cards view', () => {
    cy.contains(
      'This dashboard will help you check the search results with ease.'
    )
    cy.contains('Set your API key (optional)')
    cy.contains('Select an index')
  })

  it('Should display a message telling that no api key is required', () => {
    cy.get('span').contains('Api Key').parent().click()
    cy.get('div[aria-label=settings-api-key]').within(() => {
      cy.contains('Enter your admin API key (optional)')
      cy.contains(
        'You haven’t set an API key yet, if you want to set one you can read the documentation'
      )
    })
  })
})

const WAITING_TIME = Cypress.env('waitingTime')

describe(`Test search`, () => {
  before(() => {
    // Recreate the movies index with documents in it
    cy.deleteAllIndexes()
    cy.wait(WAITING_TIME)
    cy.createIndex('movies')
    cy.wait(WAITING_TIME)
    cy.fixture('movies.json').then((movies) => {
      cy.addDocuments('movies', movies)
      cy.wait(WAITING_TIME)
    })
  })

  beforeEach(() => {
    cy.visit('/')
  })

  it('Should update the results according to the user’s search', () => {
    cy.get('input[type="search"]').type('Fifth Element')
    cy.get('ul')
      .children()
      .should(($p) => {
        expect($p).to.have.length(1)
      })
  })

  it('Should display a message if there are no result for the user’s search', () => {
    cy.get('input[type="search"]').type('zz')
    cy.contains('Sorry mate, no results matching your request')
  })

  it('Should display a "Load more" button if there are more than 20 results', () => {
    cy.get('input[type="search"]')
    cy.get('ul')
      .children()
      .should(($p) => {
        expect($p).to.have.length(20)
      })
    cy.contains('Load more')
  })

  it('Should load the next documents on click on the "Load more" button', () => {
    cy.get('span').contains('Load more').parent().click()
    cy.get('ul')
      .children()
      .should(($p) => {
        expect($p).to.have.length(33)
      })
  })
})

